<?php declare(strict_types=1);namespace App\Core;final class Response{private int $status=200;private array $headers=[];private string $body='';public static function html(string $e,int $R=200):self{$D=new self();$D->status=$R;$D->body=$e;$D->headers['Content-Type']='text/html; charset=utf-8';return $D;}public static function json(mixed $v,int $p=200):self{$K=new self();$K->status=$p;$K->body=(string)json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$K->headers['Content-Type']='application/json; charset=utf-8';return $K;}public static function error(string $d,int $J=400,array $n=[]):self{return self::json(array_merge(['ok'=>false,'error'=>$d],$n),$J);}public static function redirect(string $z,int $H=302):self{$K=new self();$K->status=$H;$K->headers['Location']=$z;return $K;}public static function file(string $K,?string $F=null,?string $l=null,bool $w=false):self{$U=new self();$U->headers['Content-Type']=$l??(mime_content_type($K)?:'application/octet-stream');$U->headers['Content-Length']=(string)filesize($K);$U->headers['Content-Disposition']=($w?'inline':'attachment').'; filename="'.addslashes($F??basename($K)).'"';$U->headers['X-TP-File']=$K;return $U;}public static function raw(string $o,string $S,int $u=200):self{$O=new self();$O->status=$u;$O->body=$o;$O->headers['Content-Type']=$S;return $O;}public function withHeader(string $i,string $e):self{$this->headers[$i]=$e;return $this;}public function status():int{return $this->status;}public function send():void{if(!headers_sent()){http_response_code($this->status);foreach($this->headers as $y=>$U){if($y==='X-TP-File'){continue;}header($y.': '.$U);}}if(isset($this->headers['X-TP-File'])){readfile($this->headers['X-TP-File']);return;}echo $this->body;}}